# Hand-written topic text. Facts are kept general and every lesson links the official docs.
LESSONS = [
 dict(slug="pdas", title="Program Derived Addresses (PDAs)", docs=[("Solana docs: Program Derived Address","https://solana.com/docs/core/pda"),("Anchor docs: PDAs","https://www.anchor-lang.com/docs/basics/pda")],
  pat=r"find_program_address|findProgramAddress(Sync)?|seeds\s*=\s*\[", ext=(".rs",".ts",".tsx",".js"),
  intro="A PDA is an address derived from a program ID plus a list of seeds, deliberately chosen so that it has no private key. Only the deriving program can sign for it (via invoke_signed). Programs use PDAs as deterministic homes for state: a vault per user, a config account per program, an escrow per offer. Clients re-derive the same address from the same seeds, so nothing needs to be stored off-chain to find an account."),
 dict(slug="cpis", title="Cross-Program Invocations (CPIs)", docs=[("Solana docs: Cross Program Invocation","https://solana.com/docs/core/cpi"),("Anchor docs: CPIs","https://www.anchor-lang.com/docs/basics/cpi")],
  pat=r"CpiContext::new(_with_signer)?|invoke_signed\(|\binvoke\(", ext=(".rs",),
  intro="A CPI is one program calling an instruction on another program, such as the Token Program or System Program. The caller passes the accounts the callee needs. When a PDA must authorise the call, the caller uses invoke_signed (or Anchor's CpiContext::new_with_signer) with the PDA's seeds, and the runtime treats the PDA as a signer for that call only."),
 dict(slug="spl-tokens", title="SPL Tokens: mints, accounts and transfers", docs=[("Solana docs: Tokens on Solana","https://solana.com/docs/tokens"),("Anchor docs: SPL Token basics","https://www.anchor-lang.com/docs/tokens")],
  pat=r"token::transfer(_checked)?|transfer_checked|createTransferInstruction|createTransferCheckedInstruction|getOrCreateAssociatedTokenAccount|get_associated_token_address|mint_to\(|createMint\(", ext=(".rs",".ts",".tsx",".js"),
  intro="Fungible tokens on Solana are accounts owned by the Token Program. A mint account defines supply and decimals, and a token account holds a balance of one mint for one owner. The Associated Token Account (ATA) is the canonical token account address for a wallet and mint. Transfers are instructions to the Token Program. The checked variants also pass the mint and decimals so mistakes fail loudly."),
 dict(slug="token-2022", title="Token-2022 (Token Extensions)", docs=[("Solana docs: Token Extensions","https://solana.com/docs/tokens/extensions"),("Solana Program Library: Token-2022","https://www.solana-program.com/docs/token-2022")],
  pat=r"TOKEN_2022_PROGRAM_ID|spl_token_2022|token_2022|Token2022|ExtensionType", ext=(".rs",".ts",".tsx",".js"),
  intro="Token-2022 is a separate token program with the same core layout as the original Token Program, plus optional extensions configured when the mint is created: transfer fees, metadata pointers, transfer hooks, non-transferable tokens and more. Code has to pass the right token program ID. Anchor's token_interface lets one instruction accept either program."),
 dict(slug="escrow", title="Escrow patterns", docs=[("Solana program examples (escrow)","https://github.com/solana-developers/program-examples/tree/main/tokens/escrow"),("Anchor docs","https://www.anchor-lang.com/docs")],
  pat=r"escrow", ext=(".rs",), pathpat=r"escrow",
  intro="An escrow holds assets in a program-controlled account, usually a token account whose authority is a PDA, until agreed conditions are met. The usual lifecycle is make (deposit and record terms), take (counterparty pays and receives), and refund or cancel (the maker reclaims). Security depends on checking every account relationship and closing accounts so rent is returned."),
 dict(slug="staking", title="Staking and reward accrual", docs=[("Solana docs: Staking","https://solana.com/docs/references/staking"),("Anchor docs","https://www.anchor-lang.com/docs")],
  pat=r"\bstake\b|staking|reward_per|rewards?_rate", ext=(".rs",), pathpat=r"stak",
  intro="Program-level staking usually means locking tokens or NFTs in a PDA-owned vault and tracking per-user state (amount, timestamps, reward debt) in a PDA keyed by the user. Rewards are often computed lazily from the Clock sysvar when the user interacts, instead of being pushed on a schedule. This is separate from native SOL stake accounts delegated to validators."),
 dict(slug="nfts", title="NFTs with Metaplex", docs=[("Metaplex developer docs","https://developers.metaplex.com/"),("Solana docs: Tokens","https://solana.com/docs/tokens")],
  pat=r"mpl_token_metadata|@metaplex-foundation/(mpl-token-metadata|umi|js|mpl-core)|createNft\(|mpl_core|CreateV1", ext=(".rs",".ts",".tsx",".js"),
  intro="Most Solana NFTs follow Metaplex standards. Token Metadata attaches a metadata account to a supply-1 mint, and Metaplex Core is a newer single-account asset standard. Code typically builds these instructions with the Umi framework on the client, or calls the Metaplex programs through CPI from a program."),
 dict(slug="compressed-nfts", title="Compressed NFTs and state compression", docs=[("Solana docs: State Compression","https://solana.com/developers/guides/advanced/state-compression"),("Metaplex Bubblegum","https://developers.metaplex.com/bubblegum")],
  pat=r"bubblegum|spl_account_compression|ConcurrentMerkleTree|createTree\(|mintToCollectionV1|mintV1\(", ext=(".rs",".ts",".tsx",".js"),
  intro="Compressed NFTs store a hash of each asset in a concurrent Merkle tree account instead of in separate accounts, which makes minting millions of assets cheap. Asset data is reconstructed by indexers through the DAS API, and transfers need a Merkle proof. Metaplex Bubblegum is the program that mints and manages them."),
 dict(slug="oracles", title="Oracles: Pyth and Switchboard", docs=[("Pyth on Solana","https://docs.pyth.network/price-feeds/use-real-time-data/solana"),("Switchboard docs","https://docs.switchboard.xyz/")],
  pat=r"pyth|switchboard|PriceUpdateV2|get_price_no_older_than", ext=(".rs",".ts",".tsx",".js"),
  intro="Programs can't fetch off-chain data, so oracles publish it into accounts the program reads. A Pyth consumer passes a price update account into the instruction and checks freshness (for example a maximum age) and confidence before using the price. Never trust an oracle account without verifying its owner and feed ID."),
 dict(slug="solana-pay", title="Solana Pay", docs=[("Solana Pay docs","https://docs.solanapay.com/"),("Solana Pay spec","https://github.com/anza-xyz/solana-pay/blob/master/SPEC.md")],
  pat=r"@solana/pay|encodeURL\(|createQR\(|findReference\(|validateTransfer\(", ext=(".ts",".tsx",".js",".jsx"),
  intro="Solana Pay is a URL standard for requesting payments. A transfer request encodes recipient, amount, SPL token and a unique reference public key, and a wallet scanning the QR builds the transaction itself. A merchant finds the payment on-chain by the reference key and validates it. Transaction requests let a server build an arbitrary transaction for the wallet to sign."),
 dict(slug="blinks-actions", title="Blinks and Solana Actions", docs=[("Solana docs: Actions and Blinks","https://solana.com/docs/advanced/actions"),("Dialect Blinks docs","https://docs.dialect.to/")],
  pat=r"@solana/actions|ActionGetResponse|ActionPostResponse|createPostResponse|ACTIONS_CORS_HEADERS", ext=(".ts",".tsx",".js"),
  intro="A Solana Action is an HTTP API. GET returns metadata (title, icon, buttons), and POST receives the user's account and returns a serialized transaction for the wallet to sign. A Blink is a link that clients unfurl into that interactive card. Servers must send the CORS headers the spec requires and should serve an actions.json at the domain root."),
 dict(slug="ai-agents", title="AI agents on Solana", docs=[("Solana docs: AI","https://solana.com/developers/ai"),("Solana Agent Kit","https://github.com/sendaifun/solana-agent-kit")],
  pat=r"solana-agent-kit|SolanaAgentKit|@elizaos|createSolanaTools|x402", ext=(".ts",".tsx",".js",".py"),
  intro="Agent projects give an LLM a set of tools (functions) that read chain state or build and sign transactions, usually with a dedicated, limited-balance keypair or a delegated session. The important design choices are which tools exist, how signing is gated, and how outputs are validated before anything reaches mainnet."),
 dict(slug="transactions", title="Building and sending transactions from a client", docs=[("Solana docs: Transactions","https://solana.com/docs/core/transactions"),("Solana docs: Fees","https://solana.com/docs/core/fees")],
  pat=r"sendAndConfirmTransaction|sendTransaction\(|ComputeBudgetProgram|VersionedTransaction|getLatestBlockhash", ext=(".ts",".tsx",".js"),
  intro="A transaction bundles instructions, a recent blockhash and signatures. Clients fetch a recent blockhash, add instructions (often including compute-budget instructions for priority fees), sign, send, and confirm at a chosen commitment level. Versioned transactions add address lookup tables so more accounts fit."),
 dict(slug="account-constraints", title="Anchor account constraints", docs=[("Anchor docs: Account constraints","https://www.anchor-lang.com/docs/references/account-constraints")],
  pat=r"#\[account\((init|mut|has_one|constraint|close|seeds)", ext=(".rs",),
  intro="In Anchor, the #[derive(Accounts)] struct is where most security lives. Constraints such as init, mut, has_one, seeds/bump, constraint = ... and close are checked before your handler runs. Reading a program's accounts structs tells you exactly which relationships it enforces."),
]
NOTES = [
 (r"find_program_address|findProgramAddress", "derives a PDA from seeds and the program ID and returns the address with its canonical bump."),
 (r"seeds\s*=", "declares the PDA seeds. Anchor re-derives the address and rejects the account if it doesn't match."),
 (r"\bbump\b", "uses the bump seed, the extra byte that pushes the derived address off the ed25519 curve."),
 (r"CpiContext::new_with_signer|invoke_signed", "makes a CPI signed by a PDA. The signer seeds prove the program controls that address."),
 (r"CpiContext::new\b|\binvoke\(", "makes a cross-program invocation into another program."),
 (r"transfer_checked|TransferChecked", "a checked token transfer, which also verifies the mint and decimals."),
 (r"token::transfer|createTransferInstruction", "an SPL token transfer through the Token Program."),
 (r"mint_to|MintTo", "mints new tokens. The mint authority must sign."),
 (r"init_if_needed", "creates the account only if it doesn't exist. Watch for re-initialisation bugs."),
 (r"#\[account\(\s*init|\binit,", "creates and pays for a new account. Space and payer must be specified."),
 (r"has_one", "checks that a stored pubkey field matches the passed account."),
 (r"close\s*=", "closes the account at the end of the instruction and refunds its lamports."),
 (r"require!|require_keys_eq!|err!\(", "an explicit validation that aborts the instruction with an error."),
 (r"Clock::get|clock\.unix_timestamp", "reads on-chain time from the Clock sysvar."),
 (r"TOKEN_2022_PROGRAM_ID|token_2022|Token2022", "targets the Token-2022 program instead of the original Token Program."),
 (r"getLatestBlockhash", "fetches a recent blockhash. Transactions expire if it gets too old."),
 (r"ComputeBudgetProgram", "sets the compute-unit limit or price (priority fee)."),
 (r"sendAndConfirmTransaction|sendTransaction", "submits the signed transaction to the cluster."),
 (r"encodeURL", "encodes a Solana Pay request URL."),
 (r"findReference|validateTransfer", "finds or validates the on-chain payment by its reference key."),
 (r"ActionGetResponse", "the metadata a Blink client renders (title, icon, buttons)."),
 (r"createPostResponse|ActionPostResponse", "returns the serialized transaction the wallet will sign."),
 (r"get_price_no_older_than|PriceUpdateV2", "reads a Pyth price and enforces a maximum age."),
 (r"checked_(add|sub|mul|div)", "uses checked arithmetic so overflow fails instead of wrapping."),
 (r"Signer<", "requires this account to have signed the transaction."),
 (r"SolanaAgentKit|solana-agent-kit", "wires up Solana Agent Kit, which exposes on-chain actions as LLM tools."),
 (r"x402", "uses x402, an HTTP 402 pattern where an agent pays per request with an on-chain payment."),
 (r"\bstake[ds]?\b|staking", "touches staking state: the amount locked and when it was locked."),
 (r"msg!\(", "logs to the program log, which is visible in explorers and the test output."),
 (r"emit!\(", "emits an Anchor event that clients can parse from the logs."),
]
